INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wheels', 'Speed Race is a 1974 arcade racing video game developed and manufactured by Taito and released under the titles "Racer" and "Wheels" in North America by distributor Midway Manufacturing in 1975. Designed by Tomohiro Nishikado, the gameplay involves the player using the attached steering wheel to maneuver a car alongside a fast vertical scrolling road. The objective is to score points by driving past other cars without colliding with them; more points are awarded for driving faster. Players must do this under a 90-second time limit, which ends the game when it runs out. The gameplay concepts were adapted from two earlier driving electro-mechanical games: Kasco''s Mini Drive (1958) and Taito''s Super Road 7 (1970).
