INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Cup', 'A soccer-themed ball-and-paddle game by Atari released in conjuction with the 1974 FIFA World Cup held in West Germany. It was the first Atari arcade game to be produced in a cocktail format.' FROM games WHERE igdb_id = 174657 ON CONFLICT (game_id, language_code) DO NOTHING;
