INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TV Basketball', 'Released in the arcades in april 1974, Basketball was a landmark title, notable for several firsts in video gaming. It was the first basketball video game, the first video game to use sprites, and the first to represent human characters. It is also the first known Japanese-developed game to be released in North America.' FROM games WHERE igdb_id = 16979 ON CONFLICT (game_id, language_code) DO NOTHING;
