INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spasim', 'Spasim (abbreviation of ''space simulation'') was a 32-player 3D networked computer game by Jim Bowery involving 4 planetary systems with up to 8 players per planetary system, released in March 1, 1974. Jim Bowery claims that it is the very first 3D multiplayer game and has offered reward of US $500 to anyone who could document an example of a multiplayer 3D virtual reality game prior to Spasim. In Spasim the players flew around in space and to each other they appeared as wire-frame space ships. Their positions were updated about every second.
