INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Trader', 'Star Trader is a 1974 video game and an early example of the space trading genre. Seemingly based on Isaac Asimov’s Foundation series of novels, Star Trader presents a star map of the galaxy in which the players move about and make money from trading and establishing trading routes. The players travel about the star map buying and selling six types of merchandise: uranium, metals, gems, software, heavy equipment, and medicine.' FROM games WHERE igdb_id = 16976 ON CONFLICT (game_id, language_code) DO NOTHING;
