INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Airfight', 'Airfight is an early 3D graphics-based multi-user flight simulator, created on the University of Illinois Urbana-Champaign (UIUC) Control Data Corporation (CDC) PLATO system.
