INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gran Trak 10', 'Gran Trak 10 was a single-player racing arcade game released by Atari in 1974. The player raced against the clock, accumulating as many points as possible. Primitive diode-based ROM was used to store the sprites for the car, score and game timer, and the race track. The game''s controls — steering wheel, four-position gear shifter, and accelerator and brake foot pedals — were also all firsts for arcade games.' FROM games WHERE igdb_id = 7429 ON CONFLICT (game_id, language_code) DO NOTHING;
